package factoryv2

import (
	"chain"
	"chain/banker"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	pkgPath          = "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv2"
	nativeDenom      = "ugnot"
	defaultLaunchFee = int64(1_000_000_000) // 1000 GNOT
	maxNameLen       = 64
	maxImageLen      = 200
	maxSupplyBound   = 1_000_000
	maxRoyaltyBps    = 1000
	maxSymbolLen     = 11
	maxSlugLen       = 11
	minSlugLen       = 2
)

type collection struct {
	slug       string
	name       string
	symbol     string
	cover      string
	pkg        string
	creator    address
	maxSupply  int
	mintPrice  int64
	minted     int
	royaltyBps int
}

var (
	bySlug    avl.Tree
	byPkg     avl.Tree
	pending   avl.Tree
	inited    bool
	admin     address
	self      address
	launchFee int64
	seenBank  int64
)

func Init(cur realm) {
	if inited {
		panic("factory: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	admin = cur.Previous().Address()
	self = cur.Address()
	bySlug = avl.Tree{}
	byPkg = avl.Tree{}
	pending = avl.Tree{}
	launchFee = defaultLaunchFee
	seenBank = bankUgnot()
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

func Address() address {
	return chain.PackageAddress(pkgPath)
}

func LaunchFee() int64 {
	requireInit()
	return launchFee
}

func Admin() string {
	requireInit()
	return admin.String()
}

func SetLaunchFee(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot < 0 {
		panic("factory: launch fee")
	}
	launchFee = ugnot
	chain.Emit("SetLaunchFee", "ugnot", strconv.FormatInt(ugnot, 10))
}

func CreditLaunchFee(cur realm) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	pkg := prev.PkgPath()
	if pending.Has(pkg) {
		panic("factory: already credited")
	}
	if byPkg.Has(pkg) {
		panic("factory: already registered")
	}
	now := bankUgnot()
	if now < seenBank {
		panic("factory: bank")
	}
	if now-seenBank != launchFee {
		panic("factory: launch fee")
	}
	seenBank = now
	pending.Set(pkg, true)
	chain.Emit("CreditLaunchFee", "pkg", pkg)
}

func Register(cur realm, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	creatorRlm := prev.Previous()
	if !creatorRlm.IsUserCall() {
		panic("factory: EOA creator")
	}
	pkg := prev.PkgPath()
	if !pending.Has(pkg) {
		panic("factory: launch fee")
	}
	pending.Remove(pkg)
	register(pkg, creatorRlm.Address(), name, symbol, cover, maxSupply, mintPrice, royaltyBps)
}

func NoteMinted(cur realm, n int) {
	requireInit()
	if n < 0 {
		panic("factory: minted")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.minted = n
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func NoteRoyalty(cur realm, bps int) {
	requireInit()
	if bps < 0 || bps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.royaltyBps = bps
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func CollectionOf(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return c.pkg
}

func CollectionAddr(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return chain.PackageAddress(c.pkg).String()
}

func RoyaltyOf(slug string) int {
	requireInit()
	c := mustBySlug(slug)
	return c.royaltyBps
}

func ListCollections() string {
	requireInit()
	out := ""
	bySlug.Iterate("", "", func(_ string, value any) bool {
		c := value.(*collection)
		if out != "" {
			out += "\n"
		}
		out += c.slug + "|" + c.name + "|" + c.cover + "|" + c.pkg + "|" + strconv.FormatInt(c.mintPrice, 10) + "|" + strconv.Itoa(c.maxSupply) + "|" + strconv.Itoa(c.minted) + "|" + c.creator.String() + "|" + chain.PackageAddress(c.pkg).String() + "|" + strconv.Itoa(c.royaltyBps)
		return false
	})
	return out
}

func Withdraw(cur realm) {
	requireAdmin(cur)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	ugnot := bk.GetCoins(self).AmountOf(nativeDenom)
	if ugnot <= 0 {
		panic("factory: no funds")
	}
	seenBank = 0
	bk.SendCoins(self, admin, chain.Coins{{Denom: nativeDenom, Amount: ugnot}})
	chain.Emit("Withdraw", "amount", strconv.FormatInt(ugnot, 10))
}

func TransferAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !next.IsValid() {
		panic("factory: invalid address")
	}
	if next == admin {
		panic("factory: already admin")
	}
	admin = next
	chain.Emit("TransferAdmin", "addr", next.String())
}

func Render(_ string) string {
	if !inited {
		return "# Bazaar factory\n\nCall Init first.\n"
	}
	out := "# Bazaar factory\n\n"
	out += "- launch fee: " + strconv.FormatInt(launchFee, 10) + " ugnot\n"
	out += "- collections: " + strconv.Itoa(bySlug.Size()) + "\n\n"
	lines := ListCollections()
	if lines == "" {
		out += "_No collections._\n"
	} else {
		out += "```\n" + lines + "\n```\n"
	}
	return out
}

func register(pkg string, creator address, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	if !strings.HasPrefix(pkg, "gno.land/r/") {
		panic("factory: pkg")
	}
	slug := lastElem(pkg)
	if !validSlug(slug) {
		panic("factory: slug")
	}
	if !validName(name) {
		panic("factory: name")
	}
	if !validSymbol(symbol) {
		panic("factory: symbol")
	}
	if !validImage(cover) {
		panic("factory: cover")
	}
	if maxSupply < 0 || maxSupply > maxSupplyBound {
		panic("factory: maxSupply")
	}
	if mintPrice < 0 {
		panic("factory: mintPrice")
	}
	if royaltyBps < 0 || royaltyBps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	if bySlug.Has(slug) {
		panic("factory: slug taken")
	}
	if byPkg.Has(pkg) {
		panic("factory: pkg already registered")
	}
	c := &collection{
		slug:       slug,
		name:       name,
		symbol:     symbol,
		cover:      cover,
		pkg:        pkg,
		creator:    creator,
		maxSupply:  maxSupply,
		mintPrice:  mintPrice,
		royaltyBps: int(royaltyBps),
	}
	bySlug.Set(slug, c)
	byPkg.Set(pkg, c)
	chain.Emit("Register", "slug", slug, "pkg", pkg, "creator", creator.String())
}

func requireInit() {
	if !inited {
		panic("factory: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("factory: not admin")
	}
}

func bankUgnot() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(nativeDenom)
}

func mustBySlug(slug string) *collection {
	v := bySlug.Get(slug)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func mustByPkg(pkg string) *collection {
	v := byPkg.Get(pkg)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("factory: pkg")
	}
	return pkg[i+1:]
}

func validSlug(s string) bool {
	if len(s) < minSlugLen || len(s) > maxSlugLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func validSymbol(s string) bool {
	if len(s) < 1 || len(s) > maxSymbolLen {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package foam

import (
	"chain"
	"chain/banker"
	"strconv"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/fee/v1"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv2"
)

const protocolBps = int64(50)

func List(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, self, id)
	it.listed = true
	it.seller = caller
	it.price = priceUgnot
	it.owner = self
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if it.seller != caller {
		panic("col: not seller")
	}
	it.price = priceUgnot
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func Cancel(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if caller != it.seller {
		panic("col: not seller")
	}
	grcTransfer(self, self, it.seller, id)
	it.listed = false
	it.owner = it.seller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Cancel", "id", strconv.Itoa(id))
}

func Buy(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	takeExact(it.price)
	if caller == it.seller {
		panic("col: self buy")
	}
	price := it.price
	proto := fee.ProtocolFee(price, protocolBps)
	royal := int64(0)
	if royaltyBps > 0 {
		royal = fee.ProtocolFee(price, int64(royaltyBps))
	}
	if proto+royal > price {
		panic("col: fee")
	}
	sellerAmt := price - proto - royal
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if sellerAmt > 0 {
		bk.SendCoins(self, it.seller, chain.Coins{{Denom: nativeDenom, Amount: sellerAmt}})
	}
	if royal > 0 {
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: royal}})
	}
	if proto > 0 {
		bk.SendCoins(self, factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: proto}})
	}
	grcTransfer(self, self, caller, id)
	it.listed = false
	it.owner = caller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", caller.String(), "fee", strconv.FormatInt(proto, 10))
}

func Transfer(cur realm, to address, id int) {
	caller := requireUser(cur)
	if !to.IsValid() {
		panic("col: invalid address")
	}
	if to == caller || to == self {
		panic("col: invalid address")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, to, id)
	it.owner = to
	items.Set(itemKey(id), it)
	chain.Emit("Transfer", "id", strconv.Itoa(id), "to", to.String())
}

func ProtocolBps() int64 {
	return protocolBps
}

func grcTransfer(spender, from, to address, id int) {
	err := ledger.TransferFrom(spender, from, to, itemTid(id))
	if err != nil {
		panic("col: transfer")
	}
}

package foam

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/grc721/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv2"
)

const (
	maxNameLen      = 64
	maxImageLen     = 200
	maxSupplyBound  = 1_000_000
	maxRoyaltyBps   = 1000
	nativeDenom     = "ugnot"
	dropAddCap      = 20
	dropSlotHardCap = 10000
	minSlugLen      = 2
)

type item struct {
	id       int
	name     string
	image    string
	owner    address
	seller   address
	price    int64
	listed   bool
	rarity   string
	traits   string
	revealed bool
	slot     int
}

type dropSlot struct {
	name   string
	image  string
	rarity string
	traits string
}

var (
	items      avl.Tree
	dropSlots  avl.Tree
	token      *grc721.Token
	ledger     *grc721.PrivateLedger
	tokenSeq   seqid.ID
	nextID     int
	minted     int
	loaded     int
	maxSupply  int
	mintPrice  int64
	royaltyBps int
	paused     bool
	inited     bool
	creator    address
	self       address
	colName    string
	colSymbol  string
	colCover   string
	slug       string
)

func Init(cur realm, name, symbol, cover string, maxSupplyN int, mintPriceUgnot int64, royalty int64) {
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if len(symbol) < 1 || len(symbol) > grc721.MaxSymbolLen {
		panic("col: symbol")
	}
	pathSlug := lastElem(cur.PkgPath())
	if !validPkgName(pathSlug) {
		panic("col: slug")
	}
	if maxSupplyN < 0 || maxSupplyN > maxSupplyBound {
		panic("col: maxSupply")
	}
	if mintPriceUgnot < 0 {
		panic("col: mintPrice")
	}
	if royalty < 0 || royalty > maxRoyaltyBps {
		panic("col: royalty")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(cover) {
		panic("col: cover")
	}
	if inited {
		panic("col: already initialized")
	}
	slug = pathSlug
	takeLaunchFee(cur)
	tok, led := grc721.NewToken(name, symbol, tokenSeq.Next(), cur)
	token = tok
	ledger = led
	creator = cur.Previous().Address()
	self = cur.Address()
	colName = name
	colSymbol = symbol
	colCover = cover
	maxSupply = maxSupplyN
	mintPrice = mintPriceUgnot
	royaltyBps = int(royalty)
	items = avl.Tree{}
	dropSlots = avl.Tree{}
	loaded = 0
	inited = true
	factory.CreditLaunchFee(cross(cur))
	factory.Register(cross(cur), name, symbol, cover, maxSupplyN, mintPriceUgnot, royalty)
	chain.Emit("Init", "creator", creator.String(), "slug", slug)
}

func Mint(cur realm, name, imageURL string) int {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	id := mintTo(cur, caller, name, imageURL)
	chain.Emit("Mint", "id", strconv.Itoa(id), "owner", caller.String())
	return id
}

func PublicMint(cur realm) int {
	caller := requireUser(cur)
	takeExact(mintPrice)
	name := colName + " #" + strconv.Itoa(minted+1)
	image := publicImage()
	var slot *dropSlot
	slotIndex := -1
	if loaded > 0 {
		if minted >= loaded {
			panic("col: no slot")
		}
		v := dropSlots.Get(slotKey(minted))
		if v == nil {
			panic("col: no slot")
		}
		slot = v.(*dropSlot)
		name = slot.name
		image = slot.image
		slotIndex = minted
	}
	id := mintTo(cur, caller, name, image)
	if slot != nil {
		applySlot(id, slot, slotIndex)
	}
	if mintPrice > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: mintPrice}})
	}
	chain.Emit("PublicMint", "id", strconv.Itoa(id), "n", strconv.Itoa(minted))
	return id
}

func AddDropItems(cur realm, blob string) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	lines := splitDropLines(blob)
	if len(lines) < 1 || len(lines) > dropAddCap {
		panic("col: slots")
	}
	if loaded+len(lines) > slotCap() {
		panic("col: slots")
	}
	for _, line := range lines {
		name, image, rarity, traits := parseDropLine(line)
		if !validName(name) {
			panic("col: name")
		}
		if !validImage(image) {
			panic("col: image")
		}
		if !validRarity(rarity) {
			panic("col: rarity")
		}
		if !validTraits(traits) {
			panic("col: traits")
		}
		dropSlots.Set(slotKey(loaded), &dropSlot{name: name, image: image, rarity: rarity, traits: traits})
		loaded++
	}
	chain.Emit("AddDropItems", "slug", slug, "loaded", strconv.Itoa(loaded))
}

func ListDropSlots() string {
	requireInit()
	out := ""
	for i := 0; i < loaded; i++ {
		v := dropSlots.Get(slotKey(i))
		if v == nil {
			continue
		}
		s := v.(*dropSlot)
		if out != "" {
			out += "\n"
		}
		out += strconv.Itoa(i) + "|" + s.name + "|" + s.image + "|" + s.rarity + "|" + s.traits
	}
	return out
}

func LoadedOf() int {
	requireInit()
	return loaded
}

func PauseMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = true
	chain.Emit("PauseMint", "slug", slug)
}

func ResumeMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = false
	chain.Emit("ResumeMint", "slug", slug)
}

func OwnerOf(id int) address {
	return mustItem(id).owner
}

func GrcName() string {
	requireInit()
	return token.GetName()
}

func GrcSymbol() string {
	requireInit()
	return token.GetSymbol()
}

func GrcBalanceOf(addr string) int64 {
	requireInit()
	who := address(addr)
	if !who.IsValid() {
		return 0
	}
	n, err := token.BalanceOf(who)
	if err != nil {
		return 0
	}
	return n
}

func GrcOwnerOf(id int) string {
	requireInit()
	owner, err := token.OwnerOf(itemTid(id))
	if err != nil {
		panic("col: owner")
	}
	return owner.String()
}

func TokenURI(id int) string {
	return mustItem(id).image
}

func SellerOf(id int) address {
	return mustItem(id).seller
}

func PriceOf(id int) int64 {
	return mustItem(id).price
}

func NameOf(id int) string {
	return mustItem(id).name
}

func ImageOf(id int) string {
	return mustItem(id).image
}

func Listed(id int) bool {
	return mustItem(id).listed
}

func NextID() int {
	return nextID
}

func CollectionOf(_ int) string {
	requireInit()
	return slug
}

func ItemLine(id int) string {
	it := mustItem(id)
	return strconv.Itoa(it.id) + "|" + it.name + "|" + it.owner.String() + "|" + it.seller.String() + "|" + strconv.FormatInt(it.price, 10) + "|" + strconv.FormatBool(it.listed) + "|" + it.image + "|" + slug + "|" + it.rarity + "|" + it.traits + "|" + strconv.FormatBool(it.revealed) + "|" + strconv.Itoa(it.slot)
}

func ListOpen() string {
	requireInit()
	out := ""
	n := 0
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if !it.listed {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += ItemLine(it.id)
		n++
		return false
	})
	return out
}

func TokensOf(owner address) string {
	requireInit()
	out := ""
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if it.owner != owner {
			return false
		}
		if out != "" {
			out += ","
		}
		out += strconv.Itoa(it.id)
		return false
	})
	return out
}

func Creator() string {
	requireInit()
	return creator.String()
}

func MintPrice() int64 {
	requireInit()
	return mintPrice
}

func MaxSupply() int {
	requireInit()
	return maxSupply
}

func Minted() int {
	requireInit()
	return minted
}

func RoyaltyBps() int {
	requireInit()
	return royaltyBps
}

func SetRoyalty(cur realm, bps int) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	if minted != 0 {
		panic("col: minted")
	}
	if bps < 0 || bps > maxRoyaltyBps {
		panic("col: royalty")
	}
	royaltyBps = bps
	factory.NoteRoyalty(cross(cur), bps)
	chain.Emit("SetRoyalty", "slug", slug, "bps", strconv.Itoa(bps))
}

func RarityOf(id int) string {
	return mustItem(id).rarity
}

func TraitsOf(id int) string {
	return mustItem(id).traits
}

func Render(_ string) string {
	if !inited {
		return "# Collection\n\nCall Init first.\n"
	}
	out := "# " + colName + " ($" + colSymbol + ")\n\n"
	out += "- minted: " + strconv.Itoa(minted) + "\n"
	out += "- mint price: " + strconv.FormatInt(mintPrice, 10) + " ugnot\n\n"
	open := ListOpen()
	if open == "" {
		out += "_No open listings._\n"
	} else {
		out += "```\n" + open + "\n```\n"
	}
	return out
}

func mintTo(cur realm, caller address, name, imageURL string) int {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if paused {
		panic("col: paused")
	}
	if maxSupply > 0 && minted >= maxSupply {
		panic("col: sold out")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(imageURL) {
		panic("col: image")
	}
	nextID++
	id := nextID
	it := &item{
		id:       id,
		name:     name,
		image:    imageURL,
		owner:    caller,
		rarity:   rarityOf(id),
		revealed: true,
		slot:     -1,
	}
	items.Set(itemKey(id), it)
	err := ledger.Mint(caller, itemTid(id))
	if err != nil {
		panic("col: mint")
	}
	minted++
	factory.NoteMinted(cross(cur), minted)
	return id
}

func takeLaunchFee(cur realm) {
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("col: extra denoms")
	}
	fee := factory.LaunchFee()
	if sent.AmountOf(nativeDenom) != fee {
		panic("col: launch fee")
	}
	if fee > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: fee}})
	}
}

func takeExact(want int64) {
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("col: extra denoms")
	}
	if sent.AmountOf(nativeDenom) != want {
		panic("col: wrong payment")
	}
}

func publicImage() string {
	img := "/samples/" + slug + "-0" + strconv.Itoa(minted+1) + ".png"
	if validImage(img) {
		return img
	}
	return colCover
}

func requireInit() {
	if !inited {
		panic("col: call Init first")
	}
}

func requireUser(cur realm) address {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	return cur.Previous().Address()
}

func itemTid(id int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(id))
}

func mustItem(id int) *item {
	v := items.Get(itemKey(id))
	if v == nil {
		panic("col: unknown item")
	}
	return v.(*item)
}

func itemKey(id int) string {
	return strconv.Itoa(id)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("col: pkg")
	}
	return pkg[i+1:]
}

func slotKey(i int) string {
	return strconv.Itoa(i)
}

func slotCap() int {
	if maxSupply > 0 {
		return maxSupply
	}
	return dropSlotHardCap
}

func applySlot(id int, s *dropSlot, slotIndex int) {
	it := mustItem(id)
	it.name = s.name
	it.image = s.image
	if s.rarity != "" {
		it.rarity = s.rarity
	}
	it.traits = s.traits
	it.revealed = true
	it.slot = slotIndex
	items.Set(itemKey(id), it)
}

func splitDropLines(blob string) []string {
	raw := strings.Split(blob, "\n")
	out := make([]string, 0, len(raw))
	for _, line := range raw {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		out = append(out, line)
	}
	return out
}

func parseDropLine(line string) (string, string, string, string) {
	parts := strings.Split(line, "|")
	name := ""
	image := ""
	rarity := ""
	traits := ""
	if len(parts) > 0 {
		name = strings.TrimSpace(parts[0])
	}
	if len(parts) > 1 {
		image = strings.TrimSpace(parts[1])
	}
	if len(parts) > 2 {
		rarity = strings.TrimSpace(parts[2])
	}
	if len(parts) > 3 {
		traits = strings.TrimSpace(parts[3])
	}
	return name, image, rarity, traits
}

func validRarity(s string) bool {
	if s == "" {
		return true
	}
	return s == "Common" || s == "Uncommon" || s == "Rare" || s == "Epic" || s == "Legendary"
}

func validTraits(s string) bool {
	if s == "" {
		return true
	}
	if len(s) > 200 {
		return false
	}
	if strings.ContainsAny(s, "\n\r|") {
		return false
	}
	n := 0
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			return false
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			return false
		}
		if !asciiSet(key, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		if !asciiSet(val, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		n++
		if n > 8 {
			return false
		}
	}
	return n >= 1
}

func validPkgName(s string) bool {
	if len(s) < minSlugLen || len(s) > grc721.MaxSymbolLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func rarityOf(id int) string {
	r := id % 10
	if r == 0 {
		return "Legendary"
	}
	if r == 1 {
		return "Common"
	}
	if r == 2 {
		return "Uncommon"
	}
	if r == 3 {
		return "Rare"
	}
	if r == 4 {
		return "Epic"
	}
	if r <= 7 {
		return "Uncommon"
	}
	return "Common"
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package mist

import (
	"chain"
	"chain/banker"
	"strconv"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/fee/v1"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv2"
)

const protocolBps = int64(50)

func List(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, self, id)
	it.listed = true
	it.seller = caller
	it.price = priceUgnot
	it.owner = self
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if it.seller != caller {
		panic("col: not seller")
	}
	it.price = priceUgnot
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func Cancel(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if caller != it.seller {
		panic("col: not seller")
	}
	grcTransfer(self, self, it.seller, id)
	it.listed = false
	it.owner = it.seller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Cancel", "id", strconv.Itoa(id))
}

func Buy(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	takeExact(it.price)
	if caller == it.seller {
		panic("col: self buy")
	}
	price := it.price
	proto := fee.ProtocolFee(price, protocolBps)
	royal := int64(0)
	if royaltyBps > 0 {
		royal = fee.ProtocolFee(price, int64(royaltyBps))
	}
	if proto+royal > price {
		panic("col: fee")
	}
	sellerAmt := price - proto - royal
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if sellerAmt > 0 {
		bk.SendCoins(self, it.seller, chain.Coins{{Denom: nativeDenom, Amount: sellerAmt}})
	}
	if royal > 0 {
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: royal}})
	}
	if proto > 0 {
		bk.SendCoins(self, factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: proto}})
	}
	grcTransfer(self, self, caller, id)
	it.listed = false
	it.owner = caller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", caller.String(), "fee", strconv.FormatInt(proto, 10))
}

func Transfer(cur realm, to address, id int) {
	caller := requireUser(cur)
	if !to.IsValid() {
		panic("col: invalid address")
	}
	if to == caller || to == self {
		panic("col: invalid address")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, to, id)
	it.owner = to
	items.Set(itemKey(id), it)
	chain.Emit("Transfer", "id", strconv.Itoa(id), "to", to.String())
}

func ProtocolBps() int64 {
	return protocolBps
}

func grcTransfer(spender, from, to address, id int) {
	err := ledger.TransferFrom(spender, from, to, itemTid(id))
	if err != nil {
		panic("col: transfer")
	}
}

package mist

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/grc721/v0"
	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/grc721/metadata/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv2"
)

const (
	maxNameLen      = 64
	maxImageLen     = 200
	maxSupplyBound  = 1_000_000
	maxRoyaltyBps   = 1000
	nativeDenom     = "ugnot"
	dropAddCap      = 20
	dropSlotHardCap = 10000
	minSlugLen      = 2
)

type item struct {
	id       int
	name     string
	image    string
	owner    address
	seller   address
	price    int64
	listed   bool
	rarity   string
	traits   string
	revealed bool
	slot     int
}

type dropSlot struct {
	name   string
	image  string
	rarity string
	traits string
}

var (
	items      avl.Tree
	dropSlots  avl.Tree
	token      *grc721.Token
	ledger     *grc721.PrivateLedger
	metaView   *metadata.Metadata
	metaLed    *metadata.Ledger
	tokenSeq   seqid.ID
	nextID     int
	minted     int
	loaded     int
	maxSupply  int
	mintPrice  int64
	royaltyBps int
	paused     bool
	inited     bool
	creator    address
	self       address
	colName    string
	colSymbol  string
	colCover   string
	slug       string
)

func Init(cur realm, name, symbol, cover string, maxSupplyN int, mintPriceUgnot int64, royalty int64) {
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if len(symbol) < 1 || len(symbol) > grc721.MaxSymbolLen {
		panic("col: symbol")
	}
	pathSlug := lastElem(cur.PkgPath())
	if !validPkgName(pathSlug) {
		panic("col: slug")
	}
	if maxSupplyN < 0 || maxSupplyN > maxSupplyBound {
		panic("col: maxSupply")
	}
	if mintPriceUgnot < 0 {
		panic("col: mintPrice")
	}
	if royalty < 0 || royalty > maxRoyaltyBps {
		panic("col: royalty")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(cover) {
		panic("col: cover")
	}
	if inited {
		panic("col: already initialized")
	}
	slug = pathSlug
	takeLaunchFee(cur)
	tok, led := grc721.NewToken(name, symbol, tokenSeq.Next(), cur)
	token = tok
	ledger = led
	metaView, metaLed = metadata.NewMetadata(led)
	creator = cur.Previous().Address()
	self = cur.Address()
	colName = name
	colSymbol = symbol
	colCover = cover
	maxSupply = maxSupplyN
	mintPrice = mintPriceUgnot
	royaltyBps = int(royalty)
	items = avl.Tree{}
	dropSlots = avl.Tree{}
	loaded = 0
	inited = true
	factory.CreditLaunchFee(cross(cur))
	factory.Register(cross(cur), name, symbol, cover, maxSupplyN, mintPriceUgnot, royalty)
	chain.Emit("Init", "creator", creator.String(), "slug", slug)
}

func Mint(cur realm, name, imageURL string) int {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	id := mintTo(cur, caller, name, imageURL)
	writeTokenMeta(id)
	chain.Emit("Mint", "id", strconv.Itoa(id), "owner", caller.String())
	return id
}

func PublicMint(cur realm) int {
	caller := requireUser(cur)
	takeExact(mintPrice)
	name := colName + " #" + strconv.Itoa(minted+1)
	image := publicImage()
	var slot *dropSlot
	slotIndex := -1
	if loaded > 0 {
		if minted >= loaded {
			panic("col: no slot")
		}
		v := dropSlots.Get(slotKey(minted))
		if v == nil {
			panic("col: no slot")
		}
		slot = v.(*dropSlot)
		name = slot.name
		image = slot.image
		slotIndex = minted
	}
	id := mintTo(cur, caller, name, image)
	if slot != nil {
		applySlot(id, slot, slotIndex)
	}
	writeTokenMeta(id)
	if mintPrice > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: mintPrice}})
	}
	chain.Emit("PublicMint", "id", strconv.Itoa(id), "n", strconv.Itoa(minted))
	return id
}

func AddDropItems(cur realm, blob string) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	lines := splitDropLines(blob)
	if len(lines) < 1 || len(lines) > dropAddCap {
		panic("col: slots")
	}
	if loaded+len(lines) > slotCap() {
		panic("col: slots")
	}
	for _, line := range lines {
		name, image, rarity, traits := parseDropLine(line)
		if !validName(name) {
			panic("col: name")
		}
		if !validImage(image) {
			panic("col: image")
		}
		if !validRarity(rarity) {
			panic("col: rarity")
		}
		if !validTraits(traits) {
			panic("col: traits")
		}
		dropSlots.Set(slotKey(loaded), &dropSlot{name: name, image: image, rarity: rarity, traits: traits})
		loaded++
	}
	chain.Emit("AddDropItems", "slug", slug, "loaded", strconv.Itoa(loaded))
}

func ListDropSlots() string {
	requireInit()
	out := ""
	for i := 0; i < loaded; i++ {
		v := dropSlots.Get(slotKey(i))
		if v == nil {
			continue
		}
		s := v.(*dropSlot)
		if out != "" {
			out += "\n"
		}
		out += strconv.Itoa(i) + "|" + s.name + "|" + s.image + "|" + s.rarity + "|" + s.traits
	}
	return out
}

func LoadedOf() int {
	requireInit()
	return loaded
}

func PauseMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = true
	chain.Emit("PauseMint", "slug", slug)
}

func ResumeMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = false
	chain.Emit("ResumeMint", "slug", slug)
}

func OwnerOf(id int) address {
	return mustItem(id).owner
}

func GrcName() string {
	requireInit()
	return token.GetName()
}

func GrcSymbol() string {
	requireInit()
	return token.GetSymbol()
}

func GrcBalanceOf(addr string) int64 {
	requireInit()
	who := address(addr)
	if !who.IsValid() {
		return 0
	}
	n, err := token.BalanceOf(who)
	if err != nil {
		return 0
	}
	return n
}

func GrcOwnerOf(id int) string {
	requireInit()
	owner, err := token.OwnerOf(itemTid(id))
	if err != nil {
		panic("col: owner")
	}
	return owner.String()
}

func TokenURI(id int) string {
	mustItem(id)
	if metaView != nil {
		u, err := metaView.TokenURI(itemTid(id))
		if err == nil && u != "" {
			return u
		}
	}
	return tokenJSON(mustItem(id))
}

func SellerOf(id int) address {
	return mustItem(id).seller
}

func PriceOf(id int) int64 {
	return mustItem(id).price
}

func NameOf(id int) string {
	return mustItem(id).name
}

func ImageOf(id int) string {
	return mustItem(id).image
}

func Listed(id int) bool {
	return mustItem(id).listed
}

func NextID() int {
	return nextID
}

func CollectionOf(_ int) string {
	requireInit()
	return slug
}

func ItemLine(id int) string {
	it := mustItem(id)
	return strconv.Itoa(it.id) + "|" + it.name + "|" + it.owner.String() + "|" + it.seller.String() + "|" + strconv.FormatInt(it.price, 10) + "|" + strconv.FormatBool(it.listed) + "|" + it.image + "|" + slug + "|" + it.rarity + "|" + it.traits + "|" + strconv.FormatBool(it.revealed) + "|" + strconv.Itoa(it.slot)
}

func ListOpen() string {
	requireInit()
	out := ""
	n := 0
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if !it.listed {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += ItemLine(it.id)
		n++
		return false
	})
	return out
}

func TokensOf(owner address) string {
	requireInit()
	out := ""
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if it.owner != owner {
			return false
		}
		if out != "" {
			out += ","
		}
		out += strconv.Itoa(it.id)
		return false
	})
	return out
}

func Creator() string {
	requireInit()
	return creator.String()
}

func MintPrice() int64 {
	requireInit()
	return mintPrice
}

func MaxSupply() int {
	requireInit()
	return maxSupply
}

func Minted() int {
	requireInit()
	return minted
}

func RoyaltyBps() int {
	requireInit()
	return royaltyBps
}

func SetRoyalty(cur realm, bps int) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	if minted != 0 {
		panic("col: minted")
	}
	if bps < 0 || bps > maxRoyaltyBps {
		panic("col: royalty")
	}
	royaltyBps = bps
	factory.NoteRoyalty(cross(cur), bps)
	chain.Emit("SetRoyalty", "slug", slug, "bps", strconv.Itoa(bps))
}

func RarityOf(id int) string {
	return mustItem(id).rarity
}

func TraitsOf(id int) string {
	return mustItem(id).traits
}

func Render(_ string) string {
	if !inited {
		return "# Collection\n\nCall Init first.\n"
	}
	out := "# " + colName + " ($" + colSymbol + ")\n\n"
	out += "- minted: " + strconv.Itoa(minted) + "\n"
	out += "- mint price: " + strconv.FormatInt(mintPrice, 10) + " ugnot\n\n"
	open := ListOpen()
	if open == "" {
		out += "_No open listings._\n"
	} else {
		out += "```\n" + open + "\n```\n"
	}
	return out
}

func mintTo(cur realm, caller address, name, imageURL string) int {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if paused {
		panic("col: paused")
	}
	if maxSupply > 0 && minted >= maxSupply {
		panic("col: sold out")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(imageURL) {
		panic("col: image")
	}
	nextID++
	id := nextID
	it := &item{
		id:       id,
		name:     name,
		image:    imageURL,
		owner:    caller,
		rarity:   rarityOf(id),
		revealed: true,
		slot:     -1,
	}
	items.Set(itemKey(id), it)
	err := ledger.Mint(caller, itemTid(id))
	if err != nil {
		panic("col: mint")
	}
	minted++
	factory.NoteMinted(cross(cur), minted)
	return id
}

func takeLaunchFee(cur realm) {
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("col: extra denoms")
	}
	fee := factory.LaunchFee()
	if sent.AmountOf(nativeDenom) != fee {
		panic("col: launch fee")
	}
	if fee > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: fee}})
	}
}

func takeExact(want int64) {
	sent := unsafe.OriginSend()
	if len(sent) > 1 {
		panic("col: extra denoms")
	}
	if sent.AmountOf(nativeDenom) != want {
		panic("col: wrong payment")
	}
}

func publicImage() string {
	img := "/samples/" + slug + "-0" + strconv.Itoa(minted+1) + ".png"
	if validImage(img) {
		return img
	}
	return colCover
}

func requireInit() {
	if !inited {
		panic("col: call Init first")
	}
}

func requireUser(cur realm) address {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	return cur.Previous().Address()
}

func itemTid(id int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(id))
}

func mustItem(id int) *item {
	v := items.Get(itemKey(id))
	if v == nil {
		panic("col: unknown item")
	}
	return v.(*item)
}

func itemKey(id int) string {
	return strconv.Itoa(id)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("col: pkg")
	}
	return pkg[i+1:]
}

func slotKey(i int) string {
	return strconv.Itoa(i)
}

func slotCap() int {
	if maxSupply > 0 {
		return maxSupply
	}
	return dropSlotHardCap
}

func applySlot(id int, s *dropSlot, slotIndex int) {
	it := mustItem(id)
	it.name = s.name
	it.image = s.image
	if s.rarity != "" {
		it.rarity = s.rarity
	}
	it.traits = s.traits
	it.revealed = true
	it.slot = slotIndex
	items.Set(itemKey(id), it)
}

func writeTokenMeta(id int) {
	it := mustItem(id)
	uri := tokenJSON(it)
	if metaLed == nil {
		return
	}
	if err := metaLed.SetTokenURI(itemTid(id), uri); err != nil {
		panic("col: tokenURI")
	}
	if err := metaLed.SetTokenMetadata(itemTid(id), metadata.Data{
		Name:        it.name,
		Description: colName + " #" + strconv.Itoa(id),
		Image:       it.image,
		Attributes:  traitAttrs(it),
	}); err != nil {
		panic("col: metadata")
	}
}

func tokenJSON(it *item) string {
	attrs := ""
	for _, tr := range traitAttrs(it) {
		if attrs != "" {
			attrs += ","
		}
		attrs += `{"trait_type":` + jsonStr(tr.TraitType) + `,"value":` + jsonStr(tr.Value) + `}`
	}
	body := `{"name":` + jsonStr(it.name) + `,"description":` + jsonStr(colName+" #"+strconv.Itoa(it.id)) + `,"image":` + jsonStr(it.image) + `,"attributes":[` + attrs + `]}`
	return "data:application/json;charset=utf-8," + body
}

func traitAttrs(it *item) []metadata.Trait {
	out := []metadata.Trait{}
	if it.rarity != "" {
		out = append(out, metadata.Trait{TraitType: "Rarity", Value: it.rarity})
	}
	for _, part := range strings.Split(it.traits, ";") {
		part = strings.TrimSpace(part)
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			continue
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			continue
		}
		out = append(out, metadata.Trait{TraitType: key, Value: val})
	}
	return out
}

func jsonStr(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", "")
	return `"` + s + `"`
}

func splitDropLines(blob string) []string {
	raw := strings.Split(blob, "\n")
	out := make([]string, 0, len(raw))
	for _, line := range raw {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		out = append(out, line)
	}
	return out
}

func parseDropLine(line string) (string, string, string, string) {
	parts := strings.Split(line, "|")
	name := ""
	image := ""
	rarity := ""
	traits := ""
	if len(parts) > 0 {
		name = strings.TrimSpace(parts[0])
	}
	if len(parts) > 1 {
		image = strings.TrimSpace(parts[1])
	}
	if len(parts) > 2 {
		rarity = strings.TrimSpace(parts[2])
	}
	if len(parts) > 3 {
		traits = strings.TrimSpace(parts[3])
	}
	return name, image, rarity, traits
}

func validRarity(s string) bool {
	if s == "" {
		return true
	}
	return s == "Common" || s == "Uncommon" || s == "Rare" || s == "Epic" || s == "Legendary"
}

func validTraits(s string) bool {
	if s == "" {
		return true
	}
	if len(s) > 200 {
		return false
	}
	if strings.ContainsAny(s, "\n\r|") {
		return false
	}
	n := 0
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			return false
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			return false
		}
		if !asciiSet(key, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		if !asciiSet(val, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		n++
		if n > 8 {
			return false
		}
	}
	return n >= 1
}

func validPkgName(s string) bool {
	if len(s) < minSlugLen || len(s) > grc721.MaxSymbolLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func rarityOf(id int) string {
	r := id % 10
	if r == 0 {
		return "Legendary"
	}
	if r == 1 {
		return "Common"
	}
	if r == 2 {
		return "Uncommon"
	}
	if r == 3 {
		return "Rare"
	}
	if r == 4 {
		return "Epic"
	}
	if r <= 7 {
		return "Uncommon"
	}
	return "Common"
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package factoryv3

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	pkgPath          = "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv3"
	nativeDenom      = "ugnot"
	defaultLaunchFee = int64(1_000_000_000) // 1000 GNOT
	maxNameLen       = 64
	maxImageLen      = 200
	maxSupplyBound   = 1_000_000
	maxRoyaltyBps    = 1000
	maxSymbolLen     = 11
	maxSlugLen       = 11
	minSlugLen       = 2
)

type collection struct {
	slug       string
	name       string
	symbol     string
	cover      string
	pkg        string
	creator    address
	maxSupply  int
	mintPrice  int64
	minted     int
	royaltyBps int
}

var (
	bySlug    avl.Tree
	byPkg     avl.Tree
	pending   avl.Tree
	reserved  avl.Tree
	inited    bool
	admin     address
	self      address
	launchFee int64
	seenBank  int64
)

func Init(cur realm) {
	if inited {
		panic("factory: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	admin = cur.Previous().Address()
	self = cur.Address()
	bySlug = avl.Tree{}
	byPkg = avl.Tree{}
	pending = avl.Tree{}
	reserved = avl.Tree{}
	launchFee = defaultLaunchFee
	seenBank = bankUgnot()
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

func Address() address {
	return chain.PackageAddress(pkgPath)
}

func LaunchFee() int64 {
	requireInit()
	return launchFee
}

func Admin() string {
	requireInit()
	return admin.String()
}

func SetLaunchFee(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot < 0 {
		panic("factory: launch fee")
	}
	launchFee = ugnot
	chain.Emit("SetLaunchFee", "ugnot", strconv.FormatInt(ugnot, 10))
}

func CreditLaunchFee(cur realm) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	pkg := prev.PkgPath()
	if pending.Has(pkg) {
		panic("factory: already credited")
	}
	if byPkg.Has(pkg) {
		panic("factory: already registered")
	}
	now := bankUgnot()
	if now < seenBank {
		panic("factory: bank")
	}
	if now-seenBank != launchFee {
		panic("factory: launch fee")
	}
	seenBank = now
	pending.Set(pkg, true)
	chain.Emit("CreditLaunchFee", "pkg", pkg)
}

func Register(cur realm, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	creatorRlm := prev.Previous()
	if !creatorRlm.IsUserCall() {
		panic("factory: EOA creator")
	}
	pkg := prev.PkgPath()
	slug := lastElem(pkg)
	if reserved.Has(slug) {
		who := reserved.Get(slug).(address)
		if creatorRlm.Address() != who {
			panic("factory: reserved")
		}
		reserved.Remove(slug)
		if pending.Has(pkg) {
			pending.Remove(pkg)
		}
	} else {
		if !pending.Has(pkg) {
			panic("factory: launch fee")
		}
		pending.Remove(pkg)
	}
	register(pkg, creatorRlm.Address(), name, symbol, cover, maxSupply, mintPrice, royaltyBps)
}

func Reserve(cur realm, slug string) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !validSlug(slug) {
		panic("factory: slug")
	}
	if bySlug.Has(slug) || reserved.Has(slug) {
		panic("factory: slug taken")
	}
	takeFactorySend(launchFee)
	seenBank = bankUgnot()
	reserved.Set(slug, cur.Previous().Address())
	chain.Emit("Reserve", "slug", slug)
}

func CancelReserve(cur realm, slug string) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !reserved.Has(slug) {
		panic("factory: not reserved")
	}
	who := reserved.Get(slug).(address)
	if who != cur.Previous().Address() {
		panic("factory: not reserver")
	}
	if bySlug.Has(slug) {
		panic("factory: already registered")
	}
	reserved.Remove(slug)
	if launchFee > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, who, chain.Coins{{Denom: nativeDenom, Amount: launchFee}})
	}
	seenBank = bankUgnot()
	chain.Emit("CancelReserve", "slug", slug)
}

func ReservedCreator(slug string) string {
	requireInit()
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !reserved.Has(slug) {
		return ""
	}
	return reserved.Get(slug).(address).String()
}

func takeFactorySend(want int64) {
	sent := unsafe.OriginSend()
	if want == 0 {
		if len(sent) != 0 {
			panic("factory: extra denoms")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != nativeDenom || sent[0].Amount != want {
		panic("factory: wrong payment")
	}
}

func NoteMinted(cur realm, n int) {
	requireInit()
	if n < 0 {
		panic("factory: minted")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.minted = n
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func NoteRoyalty(cur realm, bps int) {
	requireInit()
	if bps < 0 || bps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.royaltyBps = bps
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func CollectionOf(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return c.pkg
}

func CollectionAddr(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return chain.PackageAddress(c.pkg).String()
}

func RoyaltyOf(slug string) int {
	requireInit()
	c := mustBySlug(slug)
	return c.royaltyBps
}

func ListCollections() string {
	requireInit()
	out := ""
	bySlug.Iterate("", "", func(_ string, value any) bool {
		c := value.(*collection)
		if out != "" {
			out += "\n"
		}
		out += c.slug + "|" + c.name + "|" + c.cover + "|" + c.pkg + "|" + strconv.FormatInt(c.mintPrice, 10) + "|" + strconv.Itoa(c.maxSupply) + "|" + strconv.Itoa(c.minted) + "|" + c.creator.String() + "|" + chain.PackageAddress(c.pkg).String() + "|" + strconv.Itoa(c.royaltyBps)
		return false
	})
	return out
}

func Withdraw(cur realm) {
	requireAdmin(cur)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	ugnot := bk.GetCoins(self).AmountOf(nativeDenom)
	if ugnot <= 0 {
		panic("factory: no funds")
	}
	seenBank = 0
	bk.SendCoins(self, admin, chain.Coins{{Denom: nativeDenom, Amount: ugnot}})
	chain.Emit("Withdraw", "amount", strconv.FormatInt(ugnot, 10))
}

func TransferAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !next.IsValid() {
		panic("factory: invalid address")
	}
	if next == admin {
		panic("factory: already admin")
	}
	admin = next
	chain.Emit("TransferAdmin", "addr", next.String())
}

func Render(_ string) string {
	if !inited {
		return "# Bazaar factory\n\nCall Init first.\n"
	}
	out := "# Bazaar factory\n\n"
	out += "- launch fee: " + strconv.FormatInt(launchFee, 10) + " ugnot\n"
	out += "- collections: " + strconv.Itoa(bySlug.Size()) + "\n\n"
	lines := ListCollections()
	if lines == "" {
		out += "_No collections._\n"
	} else {
		out += "```\n" + lines + "\n```\n"
	}
	return out
}

func register(pkg string, creator address, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	if !strings.HasPrefix(pkg, "gno.land/r/") {
		panic("factory: pkg")
	}
	slug := lastElem(pkg)
	if !validSlug(slug) {
		panic("factory: slug")
	}
	if !validName(name) {
		panic("factory: name")
	}
	if !validSymbol(symbol) {
		panic("factory: symbol")
	}
	if !validImage(cover) {
		panic("factory: cover")
	}
	if maxSupply < 0 || maxSupply > maxSupplyBound {
		panic("factory: maxSupply")
	}
	if mintPrice < 0 {
		panic("factory: mintPrice")
	}
	if royaltyBps < 0 || royaltyBps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	if bySlug.Has(slug) {
		panic("factory: slug taken")
	}
	if byPkg.Has(pkg) {
		panic("factory: pkg already registered")
	}
	c := &collection{
		slug:       slug,
		name:       name,
		symbol:     symbol,
		cover:      cover,
		pkg:        pkg,
		creator:    creator,
		maxSupply:  maxSupply,
		mintPrice:  mintPrice,
		royaltyBps: int(royaltyBps),
	}
	bySlug.Set(slug, c)
	byPkg.Set(pkg, c)
	chain.Emit("Register", "slug", slug, "pkg", pkg, "creator", creator.String())
}

func requireInit() {
	if !inited {
		panic("factory: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("factory: not admin")
	}
}

func bankUgnot() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(nativeDenom)
}

func mustBySlug(slug string) *collection {
	v := bySlug.Get(slug)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func mustByPkg(pkg string) *collection {
	v := byPkg.Get(pkg)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("factory: pkg")
	}
	return pkg[i+1:]
}

func validSlug(s string) bool {
	if len(s) < minSlugLen || len(s) > maxSlugLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func validSymbol(s string) bool {
	if len(s) < 1 || len(s) > maxSymbolLen {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package reef

import (
	"chain"
	"chain/banker"
	"strconv"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/fee/v1"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv3"
)

const protocolBps = int64(50)

func List(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, self, id)
	it.listed = true
	it.seller = caller
	it.price = priceUgnot
	it.owner = self
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 {
		panic("col: price")
	}
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if it.seller != caller {
		panic("col: not seller")
	}
	it.price = priceUgnot
	items.Set(itemKey(id), it)
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func Cancel(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	if caller != it.seller {
		panic("col: not seller")
	}
	grcTransfer(self, self, it.seller, id)
	it.listed = false
	it.owner = it.seller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Cancel", "id", strconv.Itoa(id))
}

func Buy(cur realm, id int) {
	caller := requireUser(cur)
	it := mustItem(id)
	if !it.listed {
		panic("col: not listed")
	}
	takeExact(it.price)
	if caller == it.seller {
		panic("col: self buy")
	}
	price := it.price
	proto := fee.ProtocolFee(price, protocolBps)
	royal := int64(0)
	if royaltyBps > 0 {
		royal = fee.ProtocolFee(price, int64(royaltyBps))
	}
	if proto+royal > price {
		panic("col: fee")
	}
	sellerAmt := price - proto - royal
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if sellerAmt > 0 {
		bk.SendCoins(self, it.seller, chain.Coins{{Denom: nativeDenom, Amount: sellerAmt}})
	}
	if royal > 0 {
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: royal}})
	}
	if proto > 0 {
		bk.SendCoins(self, factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: proto}})
	}
	grcTransfer(self, self, caller, id)
	it.listed = false
	it.owner = caller
	it.seller = address("")
	it.price = 0
	items.Set(itemKey(id), it)
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", caller.String(), "fee", strconv.FormatInt(proto, 10))
}

func Transfer(cur realm, to address, id int) {
	caller := requireUser(cur)
	if !to.IsValid() {
		panic("col: invalid address")
	}
	if to == caller || to == self {
		panic("col: invalid address")
	}
	it := mustItem(id)
	if it.listed {
		panic("col: listed")
	}
	if it.owner != caller {
		panic("col: not owner")
	}
	grcTransfer(caller, caller, to, id)
	it.owner = to
	items.Set(itemKey(id), it)
	chain.Emit("Transfer", "id", strconv.Itoa(id), "to", to.String())
}

func ProtocolBps() int64 {
	return protocolBps
}

func grcTransfer(spender, from, to address, id int) {
	err := ledger.TransferFrom(spender, from, to, itemTid(id))
	if err != nil {
		panic("col: transfer")
	}
}

package reef

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/grc721/v0"
	"gno.land/p/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/grc721/metadata/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	factory "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/factoryv3"
)

const (
	maxNameLen      = 64
	maxImageLen     = 200
	maxSupplyBound  = 1_000_000
	maxRoyaltyBps   = 1000
	nativeDenom     = "ugnot"
	dropAddCap      = 20
	dropSlotHardCap = 10000
	minSlugLen      = 2
)

type item struct {
	id       int
	name     string
	image    string
	owner    address
	seller   address
	price    int64
	listed   bool
	rarity   string
	traits   string
	revealed bool
	slot     int
}

type dropSlot struct {
	name   string
	image  string
	rarity string
	traits string
}

var (
	items      avl.Tree
	dropSlots  avl.Tree
	token      *grc721.Token
	ledger     *grc721.PrivateLedger
	metaView   *metadata.Metadata
	metaLed    *metadata.Ledger
	tokenSeq   seqid.ID
	nextID     int
	minted     int
	loaded     int
	maxSupply  int
	mintPrice  int64
	royaltyBps int
	paused     bool
	inited     bool
	creator    address
	self       address
	colName    string
	colSymbol  string
	colCover   string
	slug       string
)

func Init(cur realm, name, symbol, cover string, maxSupplyN int, mintPriceUgnot int64, royalty int64) {
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if len(symbol) < 1 || len(symbol) > grc721.MaxSymbolLen {
		panic("col: symbol")
	}
	pathSlug := lastElem(cur.PkgPath())
	if !validPkgName(pathSlug) {
		panic("col: slug")
	}
	if maxSupplyN < 0 || maxSupplyN > maxSupplyBound {
		panic("col: maxSupply")
	}
	if mintPriceUgnot < 0 {
		panic("col: mintPrice")
	}
	if royalty < 0 || royalty > maxRoyaltyBps {
		panic("col: royalty")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(cover) {
		panic("col: cover")
	}
	if inited {
		panic("col: already initialized")
	}
	slug = pathSlug
	reservedWho := factory.ReservedCreator(slug)
	takeLaunchFee(cur)
	tok, led := grc721.NewToken(name, symbol, tokenSeq.Next(), cur)
	token = tok
	ledger = led
	metaView, metaLed = metadata.NewMetadata(led)
	creator = cur.Previous().Address()
	self = cur.Address()
	colName = name
	colSymbol = symbol
	colCover = cover
	maxSupply = maxSupplyN
	mintPrice = mintPriceUgnot
	royaltyBps = int(royalty)
	items = avl.Tree{}
	dropSlots = avl.Tree{}
	loaded = 0
	inited = true
	if reservedWho == "" {
		factory.CreditLaunchFee(cross(cur))
	}
	factory.Register(cross(cur), name, symbol, cover, maxSupplyN, mintPriceUgnot, royalty)
	chain.Emit("Init", "creator", creator.String(), "slug", slug)
}

func Mint(cur realm, name, imageURL string) int {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	id := mintTo(cur, caller, name, imageURL)
	writeTokenMeta(id)
	chain.Emit("Mint", "id", strconv.Itoa(id), "owner", caller.String())
	return id
}

func PublicMint(cur realm) int {
	caller := requireUser(cur)
	takeExact(mintPrice)
	name := colName + " #" + strconv.Itoa(minted+1)
	image := publicImage()
	var slot *dropSlot
	slotIndex := -1
	if loaded > 0 {
		if minted >= loaded {
			panic("col: no slot")
		}
		v := dropSlots.Get(slotKey(minted))
		if v == nil {
			panic("col: no slot")
		}
		slot = v.(*dropSlot)
		name = slot.name
		image = slot.image
		slotIndex = minted
	}
	id := mintTo(cur, caller, name, image)
	if slot != nil {
		applySlot(id, slot, slotIndex)
	}
	writeTokenMeta(id)
	if mintPrice > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, creator, chain.Coins{{Denom: nativeDenom, Amount: mintPrice}})
	}
	chain.Emit("PublicMint", "id", strconv.Itoa(id), "n", strconv.Itoa(minted))
	return id
}

func AddDropItems(cur realm, blob string) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	lines := splitDropLines(blob)
	if len(lines) < 1 || len(lines) > dropAddCap {
		panic("col: slots")
	}
	if loaded+len(lines) > slotCap() {
		panic("col: slots")
	}
	for _, line := range lines {
		name, image, rarity, traits := parseDropLine(line)
		if !validName(name) {
			panic("col: name")
		}
		if !validImage(image) {
			panic("col: image")
		}
		if !validRarity(rarity) {
			panic("col: rarity")
		}
		if !validTraits(traits) {
			panic("col: traits")
		}
		dropSlots.Set(slotKey(loaded), &dropSlot{name: name, image: image, rarity: rarity, traits: traits})
		loaded++
	}
	chain.Emit("AddDropItems", "slug", slug, "loaded", strconv.Itoa(loaded))
}

func ListDropSlots() string {
	requireInit()
	out := ""
	for i := 0; i < loaded; i++ {
		v := dropSlots.Get(slotKey(i))
		if v == nil {
			continue
		}
		s := v.(*dropSlot)
		if out != "" {
			out += "\n"
		}
		out += strconv.Itoa(i) + "|" + s.name + "|" + s.image + "|" + s.rarity + "|" + s.traits
	}
	return out
}

func LoadedOf() int {
	requireInit()
	return loaded
}

func PauseMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = true
	chain.Emit("PauseMint", "slug", slug)
}

func ResumeMint(cur realm) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	paused = false
	chain.Emit("ResumeMint", "slug", slug)
}

